let [op, a, b] = readline().split(' ');

/*
// Byte approach
const nextpower = 2 ** a.length;

a = parseInt(a, 2);
b = parseInt(b, 2);

switch (op) {
    case 'AND':
        console.log(a & b); break;
    case 'OR':
        console.log(a | b); break;
    case 'XOR':
        console.log(a ^ b); break;
    case 'NAND':
        console.log(nextpower + ~(a & b)); break;
    case 'NOR':
        console.log(nextpower + ~(a | b)); break;
    case 'XNOR':
        console.log(nextpower + ~(a ^ b)); break;
}
*/

// Bit approach
a = [...a].map(Number);
b = [...b].map(Number);

let result = new Array(a.length).fill();

for (let i in result) {
    switch (op) {
        case 'AND':
            result[i] = a[i] && b[i]; break;
        case 'OR':
            result[i] = a[i] || b[i]; break;
        case 'XOR':
            result[i] = a[i] !== b[i]; break;
        case 'NAND':
            result[i] = !a[i] || !b[i]; break;
        case 'NOR':
            result[i] = !a[i] && !b[i]; break;
        case 'XNOR':
            result[i] = a[i] === b[i]; break;
    }
}

result = result.map(Number).join('');
result = parseInt(result, 2);

console.log(result);
